'use strict';

// MODULES //

var isnanf = require( '@stdlib/math-base-assert-is-nanf' );
var isinfinitef = require( '@stdlib/math-base-assert-is-infinitef' );
var absf = require( '@stdlib/math-base-special-absf' );
var expm1f = require( '@stdlib/math-base-special-expm1f' );
var lnf = require( '@stdlib/math-base-special-lnf' );
var powf = require( '@stdlib/math-base-special-powf' );
var fmodf = require( '@stdlib/math-base-special-fmodf' );
var truncf = require( '@stdlib/math-base-special-truncf' );
var f32 = require( '@stdlib/number-float64-base-to-float32' );


// VARIABLES //

var ZERO = f32( 0.0 );
var ONE = f32( 1.0 );
var HALF = f32( 0.5 );
var ONE_FIFTH = f32( 0.2 );


// MAIN //

/**
* Evaluates `bˣ - 1` for single-precision floating-point numbers.
*
* @param {number} b - base
* @param {number} x - exponent
* @returns {number} function value
*
* @example
* var y = powm1f( 2.0, 3.0 );
* // returns 7.0
*
* @example
* var y = powm1f( 4.0, 0.5 );
* // returns 1.0
*
* @example
* var y = powm1f( 0.0, 100.0 );
* // returns -1.0
*
* @example
* var y = powm1f( 100.0, 0.0 );
* // returns 0.0
*
* @example
* var y = powm1f( 0.0, 0.0 );
* // returns 0.0
*
* @example
* var y = powm1f( 3.141592653589793, 5.0 );
* // returns ~305.0197
*
* @example
* var y = powm1f( NaN, 3.0 );
* // returns NaN
*
* @example
* var y = powm1f( 5.0, NaN );
* // returns NaN
*/
function powm1f( b, x ) {
	var result;
	var y;

	b = f32( b );
	x = f32( x );

	if ( isnanf( b ) || isnanf( x ) ) {
		return NaN;
	}
	if ( x === ZERO ) {
		// Any number raised to zero (including 0) is always 1 => b^0 - 1 = 0
		return ZERO;
	}
	if ( b === ZERO ) {
		// Zero raised to any number (except 0) is always zero => 0^x - 1 = -1
		return -ONE;
	}
	if ( b < ZERO && fmodf( x, 2.0 ) === ZERO ) {
		// If `x` is even, recognize that `(-b)**x == (b)**x`...
		b = -b;
	}
	if ( b > ZERO ) {
		if (
			absf( f32( x * f32( b - ONE ) ) ) < HALF ||
			absf( x ) < ONE_FIFTH
		) {
			// No good/quick approximation for ln(b)*x, so we have to evaluate...
			y = f32( lnf( b ) * x );
			if ( y < HALF ) {
				return expm1f( y );
			}
		}
	} else if ( truncf( x ) !== x ) {
		// Exponentiation would yield a complex result...
		return NaN;
	}
	result = f32( powf( b, x ) - ONE );
	if ( isinfinitef( result ) || isnanf( result ) ) {
		return NaN;
	}
	return result;
}


// EXPORTS //

module.exports = powm1f;
